// Emits the display-copy adapter for Flutter's generated localization bundles.
// Run from the repository root. Use --patch to feed the result to apply_patch.
const fs = require('fs');
const source = JSON.parse(fs.readFileSync('lib/l10n/app_en.arb', 'utf8'));
const quote = s => JSON.stringify(s).replace(/\$/g, '\\$');
const escapeRegex = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const templates = [];
let code = "import 'app_localizations.dart';\n\n" +
  '// Generated by tool/generate_collector_copy.js from app_en.arb.\n' +
  '// Call only for app-owned display copy, never raw participant text.\n' +
  'String translateCollectorCopy(AppLocalizations l, String text) {\n' +
  "  if (l.localeName == 'en') return text;\n  final exact = switch (text) {\n";
for (const [key, value] of Object.entries(source)) {
  if (key.startsWith('@')) continue;
  const parameters = [...value.matchAll(/\{(\w+)\}/g)].map(m => m[1]);
  if (parameters.length) templates.push({key, value, parameters});
  else code += `    ${quote(value)} => l.${key},\n`;
}
code += '    _ => null,\n  };\n  if (exact != null) return exact;\n';
// Specific templates must precede broad ones (e.g. Visit {number}).
templates.sort((a, b) => b.value.replace(/\{\w+\}/g, '').length - a.value.replace(/\{\w+\}/g, '').length);
for (const {key, value, parameters} of templates) {
  const pattern = '^' + value.split(/\{\w+\}/).map(escapeRegex).join('(.+?)') + '$';
  const args = parameters.map((p, i) => p === 'label'
    ? `translateCollectorCopy(l, match.group(${i + 1})!)` : `match.group(${i + 1})!`);
  code += `  {\n    final match = RegExp(r"${pattern}", dotAll: true).firstMatch(text);\n` +
    `    if (match != null) { return l.${key}(${args.join(', ')}); }\n  }\n`;
}
code += '  return text;\n}\n';
if (process.argv.includes('--patch')) {
  const file = 'lib/l10n/collector_copy.dart';
  const old = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n').trimEnd();
  process.stdout.write('*** Begin Patch\n*** Update File: ' + process.cwd().replace(/\\/g, '/') + '/' + file +
    '\n@@\n' + old.split('\n').map(l => '-' + l).join('\n') + '\n' +
    code.trimEnd().split('\n').map(l => '+' + l).join('\n') + '\n*** End Patch\n');
} else process.stdout.write(code);
